using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Diagnostics;
using System.Collections.Generic;
using UndertaleModLib.Models;
namespace KingswayWorkshop;
public class AudioAsset {public List<string> LegacyIds {get;set;}=new();public string File {get;set;}="";public string Kind {get;set;}="sound";public string Original {get;set;}="";public string OriginalFilename {get;set;}="";}
public static class AudioAssets {
 public static string DeploymentFilename(string dir,string file){string stem=Path.GetFileNameWithoutExtension(file),ext=Path.GetExtension(file),name=stem+ext;for(int n=2;System.IO.File.Exists(Path.Combine(dir,name))&&Game.Hash(Path.Combine(dir,name))!=Game.Hash(file);n++)name=stem+"_"+n+ext;return name;}
 public static string Basename(string value){string name=Path.GetFileNameWithoutExtension(value.Replace('\\','/'));name=System.Text.RegularExpressions.Regex.Replace(name,@"[^\p{L}\p{N}_-]+","_").Trim('_','.');if(name.Length>80)name=name[..80];if(name==""||System.Text.RegularExpressions.Regex.IsMatch(name,@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$",System.Text.RegularExpressions.RegexOptions.IgnoreCase))name="audio_"+name;return name;}
 public static string NewId(Manifest m,string name){string stem=System.Text.RegularExpressions.Regex.Replace(Basename(name).ToLowerInvariant(),"[^a-z0-9_]","_").Trim('_');if(stem==""||!char.IsAsciiLetter(stem[0]))stem="audio_"+stem;stem=stem[..Math.Min(stem.Length,38)];string id=stem;for(int n=2;m.Audio.ContainsKey(id);n++)id=stem+"_"+n;return id;}
 static string Available(string directory,string stem,string extension){string name=stem;for(int n=2;System.IO.File.Exists(Validation.Within(directory,"audio/"+name+extension,false))||System.IO.File.Exists(Validation.Within(directory,"audio/"+name+"_toOgg.ogg",false));n++)name=stem+"_"+n;return name;}
 public static bool NeedsConversion(Manifest m)=>m.Audio.Any(x=>System.Text.RegularExpressions.Regex.IsMatch(x.Key,@"_[a-f0-9]{32,64}$")||System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileNameWithoutExtension(x.Value.File),@"^[a-f0-9]{32,64}$"));
 public static void ConvertLegacy(Manifest m){
  var result=new Dictionary<string,AudioAsset>();var renamed=new Dictionary<string,string>();
  foreach(var entry in m.Audio){var a=entry.Value;string file=Validation.Within(m.Directory,a.File);string logical=System.Text.RegularExpressions.Regex.Replace(entry.Key,@"_[a-f0-9]{32,64}$","");string id=logical;for(int n=2;result.ContainsKey(id);n++)id=logical+"_"+n;
   string stem=Basename(a.OriginalFilename!=""?a.OriginalFilename:id);bool converted=a.Original!="";string extension=converted?Path.GetExtension(a.Original):Path.GetExtension(a.File);string name=stem;
   for(int n=2;;n++){string candidate=Validation.Within(m.Directory,"audio/"+name+(converted?"_toOgg.ogg":extension),false);string original=Validation.Within(m.Directory,"audio/"+name+extension,false);if((!System.IO.File.Exists(candidate)||Game.Hash(candidate)==Game.Hash(file))&&(!converted||!System.IO.File.Exists(original)||Game.Hash(original)==Game.Hash(Validation.Within(m.Directory,a.Original))))break;name=stem+"_"+n;}
   string rel="audio/"+name+(converted?"_toOgg.ogg":extension),dest=Validation.Within(m.Directory,rel,false);Directory.CreateDirectory(Path.GetDirectoryName(dest));if(!System.IO.File.Exists(dest))System.IO.File.Copy(file,dest);
   if(converted){string relOriginal="audio/"+name+extension;string originalDest=Validation.Within(m.Directory,relOriginal,false);if(!System.IO.File.Exists(originalDest))System.IO.File.Copy(Validation.Within(m.Directory,a.Original),originalDest);a.Original=relOriginal;}
   a.File=rel;if(id!=entry.Key){a.LegacyIds.Add(entry.Key);renamed[entry.Key]=id;}result.Add(id,a);
  }
  m.Audio=result;foreach(var e in m.Enemies){if(renamed.TryGetValue(e.SpawnSound,out var sound))e.SpawnSound=sound;if(renamed.TryGetValue(e.Music,out var music))e.Music=music;void Nodes(List<ActionNode> list){foreach(var a in list){if((a.Kind=="sound"||(a.Kind=="text"&&a.Mode=="sound"))&&renamed.TryGetValue(a.Asset,out var asset))a.Asset=asset;Nodes(a.Children);Nodes(a.Else);foreach(var p in a.MorePaths)Nodes(p.Children);}}Nodes(e.Actions);Nodes(e.WhenAttacked);Nodes(e.Periodic);foreach(var t in e.WhenGone)Nodes(t.Children);}
 }
 public static string Converter(){var paths=(Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator).Select(p=>Path.Combine(p,"ffmpeg.exe")).ToList();string runtimes=@"C:\ProgramData\GameMakerStudio2\Cache\runtimes";if(Directory.Exists(runtimes))paths.AddRange(Directory.GetDirectories(runtimes).Select(p=>Path.Combine(p,"bin","ffmpeg.exe")));return paths.FirstOrDefault(File.Exists)??throw new Exception("WAV music needs ffmpeg. No installed converter was found; import Ogg Vorbis instead.");}
 public static void Check(string file,string kind){var data=System.IO.File.ReadAllBytes(file);if(data.Length>32*1024*1024)throw new Exception("Audio must be no larger than 32 MB");
  if(kind=="music"){if(data.Length<32||Encoding.ASCII.GetString(data,0,4)!="OggS"||!Encoding.ASCII.GetString(data.Take(256).ToArray()).Contains("\x01vorbis"))throw new Exception("Music must be Ogg Vorbis, not Opus or a renamed WAV");return;}
  if(kind!="sound")throw new Exception("Audio kind must be sound or music");
  if(data.Length<44||Encoding.ASCII.GetString(data,0,4)!="RIFF"||Encoding.ASCII.GetString(data,8,4)!="WAVE")throw new Exception("Sound effects need a 16-bit PCM WAV");bool fmt=false,pcm=false;for(int p=12;p+8<=data.Length;){string id=Encoding.ASCII.GetString(data,p,4);int size=BitConverter.ToInt32(data,p+4);if(size<0||(long)p+8+size>data.Length)throw new Exception("Truncated WAV chunk");if(id=="fmt "){if(size<16)throw new Exception("Invalid WAV format");int channels=BitConverter.ToUInt16(data,p+10),rate=BitConverter.ToInt32(data,p+12);fmt=BitConverter.ToUInt16(data,p+8)==1&&BitConverter.ToUInt16(data,p+22)==16&&channels>=1&&channels<=2&&rate>=8000&&rate<=48000;}if(id=="data")pcm=size>0;p+=8+size+(size%2);}if(!fmt||!pcm)throw new Exception("Use 16-bit PCM WAV, mono or stereo, 8–48 kHz, with audio samples");
 }
 public static Manifest Import(Store store,string id,string name,string kind,string extension,byte[] bytes,string originalFilename=""){if(!Validation.Identifier(name))throw new Exception("Use a lowercase audio name with letters, numbers, and underscores");if(extension!=".wav"&&extension!=".ogg")throw new Exception("Choose WAV or Ogg Vorbis");var m=store.List().First(x=>x.Id==id);if(m.Audio.ContainsKey(name))throw new Exception("Audio ID already exists: "+name);string temp=Path.Combine(store.Root,"Builds","audio-"+Guid.NewGuid().ToString("N")+extension);System.IO.File.WriteAllBytes(temp,bytes);string output=temp;var added=new List<string>();
  try{if(kind=="music"&&extension==".wav"){output=temp+".ogg";var psi=new ProcessStartInfo(Converter()){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};foreach(var arg in new[]{"-v","error","-y","-i",temp,"-vn","-acodec","libvorbis","-q:a","5",output})psi.ArgumentList.Add(arg);using var process=Process.Start(psi);string error=process.StandardError.ReadToEnd();if(!process.WaitForExit(60000)||process.ExitCode!=0)throw new Exception("Music conversion failed: "+error);}
   Check(output,kind);string stem=Available(m.Directory,Basename(originalFilename==""?name:originalFilename),extension),rel="audio/"+stem+(output!=temp?"_toOgg.ogg":extension),dest=Validation.Within(m.Directory,rel,false);Directory.CreateDirectory(Path.GetDirectoryName(dest));System.IO.File.Copy(output,dest,false);added.Add(dest);string original="";if(output!=temp){original="audio/"+stem+extension;string destOriginal=Validation.Within(m.Directory,original,false);System.IO.File.Copy(temp,destOriginal,false);added.Add(destOriginal);}m.Audio[name]=new(){File=rel,Kind=kind,Original=original,OriginalFilename=Path.GetFileName(originalFilename.Replace('\\','/'))};store.Save(m);return m;
  }catch{foreach(var file in added)System.IO.File.Delete(file);throw;}finally{if(System.IO.File.Exists(temp))System.IO.File.Delete(temp);if(output!=temp&&System.IO.File.Exists(output))System.IO.File.Delete(output);}
 }
}
public sealed partial class Compiler {
 string AudioKey(Manifest m,string key)=>m.Audio.ContainsKey(key)?m.Id+":"+key:key;
 void PrepareAudio(List<Manifest> mods){var code=new StringBuilder();foreach(var match in System.Text.RegularExpressions.Regex.Matches(game.Source("gml_Script_scr_LoadSounds"),@"global\.(sound_\w+) = (\d+);" ).Cast<System.Text.RegularExpressions.Match>())code.AppendLine("global.v2_audio[?"+Q(match.Groups[1].Value)+"]="+match.Groups[2].Value+";");foreach(var sound in game.Data.Sounds)code.AppendLine("global.v2_audio[?"+Q(sound.Name.Content)+"]="+sound.Name.Content+";");
  foreach(var m in mods)foreach(var pair in m.Audio){string file=Validation.Within(m.Directory,pair.Value.File);if(pair.Value.Kind=="music"){string dir=Path.Combine(Path.GetDirectoryName(root),"WorkshopAudio",m.Id);Directory.CreateDirectory(dir);string filename=AudioAssets.DeploymentFilename(dir,file);if(!System.IO.File.Exists(Path.Combine(dir,filename)))System.IO.File.Copy(file,Path.Combine(dir,filename));code.AppendLine("global.v2_music_paths[?"+Q(m.Id+":"+pair.Key)+"]="+Q("WorkshopAudio/"+m.Id+"/"+filename)+";");}
   else{string name="snd_v2_"+m.Id+"_"+pair.Key;var embedded=new UndertaleEmbeddedAudio{Name=game.Str(name),Data=System.IO.File.ReadAllBytes(file)};game.Data.EmbeddedAudio.Add(embedded);var sound=new UndertaleSound{Name=game.Str(name),Type=game.Str(".wav"),File=game.Str(name+".wav"),Flags=UndertaleSound.AudioEntryFlags.Regular|UndertaleSound.AudioEntryFlags.IsEmbedded,Volume=1,Pitch=1,AudioFile=embedded,AudioGroup=game.Data.AudioGroups.FirstOrDefault()};game.Data.Sounds.Add(sound);code.AppendLine("global.v2_audio[?"+Q(m.Id+":"+pair.Key)+"]="+name+";");}}
  foreach(var m in mods)foreach(var pair in m.Audio)foreach(var legacy in pair.Value.LegacyIds){string map=pair.Value.Kind=="music"?"global.v2_music_paths":"global.v2_audio";code.AppendLine(map+"[?"+Q(m.Id+":"+legacy)+"]="+map+"[?"+Q(m.Id+":"+pair.Key)+"]; ");}
  Queue("gml_Script_scr_v2_audio_registry",code.ToString());
 }
}
